<template>
  <div class="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/40 p-4" @click.self="close">
    <div class="my-4 w-full max-w-3xl rounded-xl bg-white shadow-xl md:my-6">
      <div class="flex flex-wrap items-center gap-2 border-b px-4 py-3">
        <h3 class="font-semibold">{{ edit ? `Edit ${doctype} ${edit.name}` : `New ${doctype}` }}</h3>
        <div class="ml-auto flex gap-2">
          <button :disabled="busy" class="rounded-md border px-3 py-1.5 text-sm" @click="save(false)">Save Draft</button>
          <button :disabled="busy" class="rounded-md px-3 py-1.5 text-sm text-white" :class="belowCost ? 'bg-amber-500 hover:bg-amber-600' : 'azzir-brand'" @click="save(true)">{{ belowCost ? 'Send for Approval' : 'Save & Submit' }}</button>
          <button class="rounded-md p-1 text-gray-400 hover:text-gray-700" @click="close">✕</button>
        </div>
      </div>

      <div class="px-4 py-3">
        <div v-if="msg" class="mb-3 rounded-md px-3 py-2 text-sm" :class="err ? 'bg-red-50 text-red-700' : 'bg-green-50 text-green-700'">{{ msg }}</div>

        <div class="mb-4 grid grid-cols-1 gap-3 md:grid-cols-3">
          <div>
            <label class="mb-1 block text-xs text-gray-500">Company</label>
            <Combo v-model="company" doctype="Company" display="name" placeholder="Select company" />
          </div>
          <div>
            <label class="mb-1 block text-xs text-gray-500">Customer</label>
            <Combo v-model="customer" doctype="Customer" display="customer_name" placeholder="Select customer" query-method="azzir_fleet.sales_api.list_customers" :query-args="{ company }" @picked="onCustomerPicked" />
          </div>
          <div>
            <label class="mb-1 block text-xs text-gray-500">Customer Name <span class="text-gray-400">(editable)</span></label>
            <input v-model="customerName" placeholder="Auto-fills from customer" class="w-full rounded-md border px-3 py-2 text-sm" />
          </div>
          <div>
            <label class="mb-1 block text-xs text-gray-500">{{ dateLabel }} <span class="text-gray-400">(editable)</span></label>
            <input v-model="docDate" type="date" class="w-full rounded-md border px-3 py-2 text-sm" />
          </div>
        </div>

        <div class="mb-4 flex flex-wrap items-center gap-x-6 gap-y-2 text-sm text-gray-700">
          <label class="flex items-center gap-2">
            <input type="checkbox" v-model="applyVat" />
            Apply VAT
            <span class="text-xs text-gray-400">(untick to remove VAT)</span>
          </label>
          <label class="flex items-center gap-2">
            <input type="checkbox" v-model="hidePartNo" />
            Hide Part Numbers on Print
          </label>
        </div>

        <!-- Buy-from-sister is per item line (tick 'From sister' on a row below).
             Only Corporate-cost-center users see those columns. -->

        <div class="rounded-lg border">
          <div class="flex items-center gap-2 border-b px-3 py-2">
            <div class="text-sm font-medium text-gray-600">Items</div>
            <button class="ml-auto rounded-md border px-2 py-1 text-xs" @click="showAddMultiple = true">Add multiple</button>
            <button class="rounded-md border px-2 py-1 text-xs" @click="addRow">+ Add item</button>
          </div>
          <div class="hidden overflow-x-auto md:block">
          <table class="min-w-full text-sm">
            <thead class="bg-gray-50 text-left text-gray-500">
              <tr><th class="px-3 py-2">Item</th><th class="px-2 py-2 w-16">Qty</th><th class="px-2 py-2 w-24">Rate</th><th class="px-2 py-2 w-44">All Warehouse</th><th class="px-2 py-2 w-44">Warehouse</th><th class="px-2 py-2 w-24 text-right">Amount</th><th></th></tr>
            </thead>
            <tbody>
              <template v-for="(row, i) in rows" :key="i">
                <tr class="border-t align-top">
                  <td class="px-2 py-2 w-64"><Combo v-model="row.item_code" doctype="Item" display="item_name" placeholder="Select item / part no." query-method="azzir_fleet.alias.item_search_for_spa" @update:model-value="(v) => onItem(i, v)" /></td>
                  <td class="px-2 py-2"><input v-model.number="row.qty" type="number" class="w-14 rounded border px-2 py-1" /></td>
                  <td class="px-2 py-2"><input v-model.number="row.rate" type="number" class="w-20 rounded border px-2 py-1" /></td>
                  <!-- All Warehouse comes FIRST: it's the input. Pick one of our groups
                       and the backend resolves the concrete leaf (ours, or a branch-
                       matched sister that has the stock) into Warehouse beside it. -->
                  <td class="px-2 py-2">
                    <div v-if="sisterEligible && row.item_code" class="w-40">
                      <Combo v-model="row.all_warehouses" doctype="Warehouse" display="name" placeholder="All Warehouses"
                        query-method="azzir_fleet.intercompany_sale.company_group_warehouses" :query-args="{ company }"
                        @update:model-value="() => onPickAllWarehouses(row)" />
                    </div>
                    <div v-else class="px-1 text-sm text-gray-300">—</div>
                  </td>
                  <!-- Warehouse: the RESOLVED leaf, filled by the All Warehouse picker —
                       read-only so it can't drift from what the backend resolved. Users
                       without the All Warehouse picker keep an editable field, otherwise
                       they'd have no way to set a warehouse at all. -->
                  <td class="px-2 py-2">
                    <div class="flex items-center gap-1">
                      <div v-if="sisterEligible" class="w-40 truncate rounded-md border bg-gray-50 px-3 py-2 text-sm text-gray-600" :title="row.warehouse">{{ row.warehouse || '—' }}</div>
                      <div v-else class="w-40"><Combo v-model="row.warehouse" doctype="Warehouse" display="name" placeholder="—" query-method="azzir_fleet.warehouse_cc.warehouse_search" :query-args="{ company }" /></div>
                      <button v-if="row.item_code" class="rounded border px-1.5 py-1 text-xs" title="See all warehouses" @click="stockRow = i">📦</button>
                    </div>
                  </td>
                  <td class="px-2 py-2 text-right">{{ fmt((row.qty || 0) * (row.rate || 0)) }}</td>
                  <td class="px-2 py-2"><button class="text-gray-400 hover:text-red-500" @click="rows.splice(i, 1)">✕</button></td>
                </tr>
                <!-- Editable item description (auto-fills from the item, override freely). -->
                <tr v-if="row.item_code">
                  <td colspan="7" class="px-2 pb-2">
                    <input v-model="row.description" placeholder="Description (editable)" class="w-full rounded border px-2 py-1 text-xs text-gray-600" />
                  </td>
                </tr>
                <!-- Per-row sister source (buy-from-sister): tick only the lines that
                     come from a sister; the rest stay normal. -->
                <tr v-if="sisterEligible">
                  <td colspan="7" class="px-2 pb-2">
                    <div class="flex flex-wrap items-center gap-2 rounded bg-amber-50 px-2 py-1 text-xs">
                      <label class="flex items-center gap-1"><input type="checkbox" v-model="row.from_sister" @change="onRowFromSister(row)" /> From sister</label>
                      <!-- Supply company / warehouse are resolved by the backend (All
                           Warehouse pick, or the sister default for the item) — shown
                           read-only so a hand edit can't contradict the resolution. -->
                      <template v-if="row.from_sister">
                        <div class="w-48 truncate rounded border bg-white px-2 py-1 text-gray-700" :title="row.supply_company">{{ row.supply_company || '—' }}</div>
                        <div class="w-56 truncate rounded border bg-white px-2 py-1 text-gray-700" :title="row.supply_warehouse">{{ row.supply_warehouse || '—' }}</div>
                      </template>
                    </div>
                  </td>
                </tr>
              </template>
              <tr v-if="!rows.length"><td colspan="7" class="px-3 py-6 text-center text-gray-400">No items.</td></tr>
            </tbody>
            <tfoot><tr class="border-t"><td colspan="5" class="px-3 py-2 text-right font-semibold">Total</td><td class="px-3 py-2 text-right font-semibold">{{ fmt(total) }}</td><td></td></tr></tfoot>
          </table>
          </div>

          <!-- MOBILE: each item as a stacked card (no horizontal scrolling) -->
          <div class="divide-y md:hidden">
            <div v-for="(row, i) in rows" :key="'m' + i" class="space-y-2 p-3">
              <div>
                <label class="mb-1 block text-xs text-gray-500">Item</label>
                <Combo v-model="row.item_code" doctype="Item" display="item_name" placeholder="Select item / part no." query-method="azzir_fleet.alias.item_search_for_spa" @update:model-value="(v) => onItem(i, v)" />
              </div>
              <div class="grid grid-cols-2 gap-2">
                <div><label class="mb-1 block text-xs text-gray-500">Qty</label><input v-model.number="row.qty" type="number" class="w-full rounded border px-2 py-1" /></div>
                <div><label class="mb-1 block text-xs text-gray-500">Rate</label><input v-model.number="row.rate" type="number" class="w-full rounded border px-2 py-1" /></div>
              </div>
              <div>
                <!-- All Warehouse first (the input), Warehouse below it (the result) —
                     same order as the desktop table. -->
                <div v-if="sisterEligible && row.item_code" class="mb-2">
                  <label class="mb-1 block text-xs text-gray-500">All Warehouse</label>
                  <Combo v-model="row.all_warehouses" doctype="Warehouse" display="name" placeholder="All Warehouses"
                    query-method="azzir_fleet.intercompany_sale.company_group_warehouses" :query-args="{ company }"
                    @update:model-value="() => onPickAllWarehouses(row)" />
                </div>
                <label class="mb-1 block text-xs text-gray-500">Warehouse</label>
                <div class="flex items-center gap-1">
                  <div v-if="sisterEligible" class="flex-1 truncate rounded-md border bg-gray-50 px-3 py-2 text-sm text-gray-600">{{ row.warehouse || '—' }}</div>
                  <div v-else class="flex-1"><Combo v-model="row.warehouse" doctype="Warehouse" display="name" placeholder="—" query-method="azzir_fleet.warehouse_cc.warehouse_search" :query-args="{ company }" /></div>
                  <button v-if="row.item_code" class="rounded border px-2 py-1 text-xs" title="See all warehouses" @click="stockRow = i">📦</button>
                </div>
              </div>
              <div v-if="row.item_code">
                <input v-model="row.description" placeholder="Description (editable)" class="w-full rounded border px-2 py-1 text-xs text-gray-600" />
              </div>
              <div v-if="sisterEligible" class="rounded bg-amber-50 px-2 py-2 text-xs">
                <label class="flex items-center gap-1"><input type="checkbox" v-model="row.from_sister" @change="onRowFromSister(row)" /> From sister</label>
                <!-- Read-only: resolved by the backend, same as the desktop view. -->
                <template v-if="row.from_sister">
                  <div class="mt-2 truncate rounded border bg-white px-2 py-1 text-gray-700">{{ row.supply_company || '—' }}</div>
                  <div class="mt-2 truncate rounded border bg-white px-2 py-1 text-gray-700">{{ row.supply_warehouse || '—' }}</div>
                </template>
              </div>
              <div class="flex items-center justify-between pt-1">
                <span class="text-sm font-medium">Amount: {{ fmt((row.qty || 0) * (row.rate || 0)) }}</span>
                <button class="text-sm text-red-500 hover:text-red-700" @click="rows.splice(i, 1)">Remove</button>
              </div>
            </div>
            <div v-if="!rows.length" class="p-4 text-center text-sm text-gray-400">No items.</div>
            <div class="flex items-center justify-between p-3 font-semibold"><span>Total</span><span>{{ fmt(total) }}</span></div>
          </div>
        </div>

        <!-- Comments (free text, saved on the document). -->
        <div class="mt-4">
          <label class="mb-1 block text-xs text-gray-500">Comments</label>
          <textarea v-model="comments" rows="2" placeholder="Notes for this document…" class="w-full rounded-md border px-3 py-2 text-sm"></textarea>
        </div>
      </div>
    </div>

    <!-- Stock modal -->
    <div v-if="stockRow !== null" class="fixed inset-0 z-[60] flex items-center justify-center bg-black/40 p-4" @click.self="stockRow = null">
      <div class="w-full max-w-lg rounded-lg bg-white p-4 shadow-xl">
        <div class="mb-2 flex items-center"><div class="font-semibold">Available stock — {{ rows[stockRow]?.item_code }}</div><button class="ml-auto text-gray-400" @click="stockRow = null">✕</button></div>
        <p class="mb-2 text-xs text-gray-500">Click a warehouse to set it on the row.</p>
        <StockTree :item-code="rows[stockRow]?.item_code" selectable @select="setWarehouse" />
      </div>
    </div>

    <!-- Add-multiple items picker -->
    <AddItemsDialog v-if="showAddMultiple" @close="showAddMultiple = false" @add="onAddMultiple" />
  </div>
</template>

<script setup>
import { ref, computed, onMounted, watch } from 'vue'
import { insertDoc, submitSalesDoc, saveDoc, itemDetails, salesDefaults, userCanBuySister, sisterDefaultForItem, resolveAllWarehouses, myAllowedWarehouses, userWarehouseForItem, fmt } from '@/utils/api.js'
import Combo from '@/components/Combo.vue'
import StockTree from '@/components/StockTree.vue'
import AddItemsDialog from '@/components/AddItemsDialog.vue'

const props = defineProps({
  doctype: String,
  edit: { type: Object, default: null },
  initial: { type: Object, default: null },
})
const emit = defineEmits(['close', 'saved'])

const defaults = ref({})
const company = ref('')
const customer = ref('')
const customerName = ref('') // editable Customer Name; auto-fills from the picked customer
const base = ref(null) // full existing doc when editing
const rows = ref([])
const busy = ref(false)
const msg = ref('')
const err = ref(false)
const stockRow = ref(null)
const showAddMultiple = ref(false) // the "Add multiple" item picker
const allowedWh = ref(null) // warehouses this user may pick; null = unrestricted
const applyVat = ref(true) // Apply VAT (default on); untick to drop VAT from the doc
const hidePartNo = ref(false) // Hide Part Numbers on the printout
const comments = ref('') // free-text document comments (azzir_comments)

// Editable document date. Sales Invoice / Delivery Note use posting_date; Quotation
// uses transaction_date. Defaults to today; the user can back- or post-date the doc.
const today = () => new Date().toISOString().slice(0, 10)
const docDate = ref(today())
const dateField = computed(() => (props.doctype === 'Quotation' ? 'transaction_date' : 'posting_date'))
const dateLabel = computed(() => (props.doctype === 'Quotation' ? 'Quotation Date' : 'Posting Date'))

// Buy-from-sister is per item row now (corporate-cost-center users). No header field.
const canBuySister = ref(false)
const sisterDoctype = (dt) => dt === 'Sales Invoice' || dt === 'Quotation'
const sisterEligible = computed(() => canBuySister.value && sisterDoctype(props.doctype))

const total = computed(() => rows.value.reduce((s, r) => s + (Number(r.qty) || 0) * (Number(r.rate) || 0), 0))
// True when any line is priced BELOW its selling (list) price — or below its
// buying price when the item has no selling price. The submit then routes to
// approval, so the button reads "Send for Approval" instead of "Save & Submit".
const belowCost = computed(() =>
  rows.value.some((r) => {
    if (!r.item_code || !(Number(r.rate) > 0)) return false
    const selling = Number(r.price_list_rate) || 0
    if (selling > 0) return Number(r.rate) < selling
    const buying = Number(r.buying_rate) || 0
    return buying > 0 && Number(r.rate) < buying
  }),
)

// Changing the company clears the picked customer (it may not belong to the new one)
// and refreshes which warehouses this user may pick.
watch(company, async (n, o) => {
  if (o) { customer.value = ''; customerName.value = '' }
  allowedWh.value = await myAllowedWarehouses(n).catch(() => null)
})
// Picking a customer auto-fills the (editable) customer name.
function onCustomerPicked(o) { customerName.value = o?.customer_name || o?.name || '' }

onMounted(async () => {
  defaults.value = await salesDefaults().catch(() => ({}))
  company.value = props.edit?.company || props.initial?.company || defaults.value.company || ''
  allowedWh.value = await myAllowedWarehouses(company.value).catch(() => null)
  if (sisterDoctype(props.doctype)) {
    canBuySister.value = await userCanBuySister().catch(() => false)
  }
  if (props.edit) {
    base.value = props.edit
    applyVat.value = props.edit.azzir_apply_vat === 0 ? false : true
    hidePartNo.value = !!props.edit.azzir_hide_part_no
    comments.value = props.edit.azzir_comments || ''
    docDate.value = props.edit[dateField.value] || today()
    customer.value = props.edit.party_name || props.edit.customer || ''
    customerName.value = props.edit.customer_name || ''
    rows.value = (props.edit.items || []).map((r) => ({ item_code: r.item_code, qty: r.qty, rate: r.rate, price_list_rate: r.price_list_rate || 0, buying_rate: 0, description: r.description || '', warehouse: r.warehouse || '', all_warehouses: '', from_sister: !!r.azzir_row_from_sister, supply_company: r.azzir_supply_company || '', supply_warehouse: r.azzir_supply_warehouse || '' }))
    if (!rows.value.length) addRow()
    fetchBuyingRates()
  } else if (props.initial) {
    customer.value = props.initial.customer || ''
    customerName.value = props.initial.customer_name || ''
    comments.value = props.initial.azzir_comments || ''
    rows.value = (props.initial.items || []).map((r) => ({ item_code: r.item_code, qty: r.qty || 1, rate: r.rate || 0, price_list_rate: r.price_list_rate || 0, buying_rate: 0, description: r.description || '', warehouse: r.warehouse || '', all_warehouses: '', from_sister: !!r.azzir_row_from_sister, supply_company: r.azzir_supply_company || '', supply_warehouse: r.azzir_supply_warehouse || '' }))
    if (!rows.value.length) addRow()
    fetchBuyingRates()
  } else {
    addRow()
  }
})
function addRow() { rows.value.push({ item_code: '', qty: 1, rate: 0, price_list_rate: 0, buying_rate: 0, description: '', warehouse: '', all_warehouses: '', from_sister: false, supply_company: '', supply_warehouse: '' }) }
// "Add multiple": one row per chosen item (skip ones already added), each auto-filled
// like a normal pick. Reuses a trailing empty row so we don't leave a blank line.
async function onAddMultiple(codes) {
  showAddMultiple.value = false
  for (const code of codes || []) {
    if (rows.value.some((r) => r.item_code === code)) continue
    if (!rows.value.length || rows.value[rows.value.length - 1].item_code) addRow()
    const idx = rows.value.length - 1
    rows.value[idx].item_code = code
    await onItem(idx, code)
  }
}
// "From sister" toggled: un-ticked -> clear supply picks; ticked -> auto-fill the
// default sister company + the in-group warehouse with the most stock of the item.
async function onRowFromSister(row) {
  if (!row.from_sister) { row.supply_company = ''; row.supply_warehouse = ''; return }
  await fillSisterDefault(row)
}
// Auto-fill a row's sister source from Azzir Fleet Settings (default company + the
// child warehouse under the default group holding the most stock of the item).
async function fillSisterDefault(row) {
  if (!row.from_sister || !row.item_code) return
  const d = await sisterDefaultForItem(row.item_code).catch(() => null)
  if (!d) return
  if (d.supply_company) row.supply_company = d.supply_company
  if (d.supply_warehouse) row.supply_warehouse = d.supply_warehouse
}
// "All Warehouses" picker: the user chose one of OUR company's group warehouses. Resolve
// it to a concrete leaf — our own if we hold stock, otherwise a branch-matched sister
// supplies and our matching leaf goes on the row. Fills warehouse + sister source.
async function onPickAllWarehouses(row) {
  if (!row.all_warehouses || !row.item_code) return
  const r = await resolveAllWarehouses(row.item_code, row.all_warehouses, company.value).catch(() => null)
  if (!r || !r.warehouse) {
    err.value = true; msg.value = `No warehouse (ours or a sister on that branch) has stock of ${row.item_code}.`
    return
  }
  row.warehouse = r.warehouse
  if (r.from_sister && r.supply_company && r.supply_warehouse) {
    row.from_sister = true
    row.supply_company = r.supply_company
    row.supply_warehouse = r.supply_warehouse
  }
}
function setWarehouse(wh) {
  if (stockRow.value !== null) {
    // Respect cost-center scoping: don't let the "see all warehouses" picker set one
    // the user isn't allowed to use (the server enforces this too).
    if (allowedWh.value && wh && !allowedWh.value.includes(wh)) {
      err.value = true; msg.value = `You can't use warehouse ${wh} — it's not in your cost centre.`
      stockRow.value = null; return
    }
    rows.value[stockRow.value].warehouse = wh
  }
  stockRow.value = null
}
function close() { emit('close') }

// Auto-fetch the price when an item is chosen (like ERPNext).
async function onItem(i, item_code) {
  if (!item_code) return
  const d = await itemDetails(item_code, customer.value, defaults.value.company, defaults.value.selling_price_list, rows.value[i].qty || 1).catch(() => ({}))
  if (d && d.price_list_rate) rows.value[i].price_list_rate = d.price_list_rate
  if (d && d.buying_rate) rows.value[i].buying_rate = d.buying_rate
  if (d && d.description && !rows.value[i].description) rows.value[i].description = d.description
  if (d && d.rate && !rows.value[i].rate) rows.value[i].rate = d.rate
  // Auto-fill the user's allowed (cost-centre) warehouse that holds this item — only
  // when the row has none yet, so a manual pick is never overridden. Same as the desk.
  if (!rows.value[i].warehouse) {
    const wh = await userWarehouseForItem(item_code, company.value).catch(() => null)
    if (wh && !rows.value[i].warehouse) rows.value[i].warehouse = wh
  }
  // If this line is sourced from a sister, refresh its sister supply for the new item.
  if (rows.value[i].from_sister) fillSisterDefault(rows.value[i])
}

// Fill in buying rates for prefilled rows (edit / next-doc) so the submit button
// can reflect below-cost immediately, without waiting for the user to touch a row.
async function fetchBuyingRates() {
  for (const r of rows.value) {
    if (!r.item_code || r.buying_rate) continue
    const d = await itemDetails(r.item_code, customer.value, defaults.value.company, defaults.value.selling_price_list, r.qty || 1).catch(() => ({}))
    if (d && d.buying_rate) r.buying_rate = d.buying_rate
  }
}

async function save(submit) {
  msg.value = ''
  if (!customer.value) { err.value = true; msg.value = 'Pick a customer.'; return }
  const sister = sisterDoctype(props.doctype) && canBuySister.value
  const items = rows.value.filter((r) => r.item_code).map((r) => {
    const it = { item_code: r.item_code, qty: r.qty || 1, rate: r.rate || 0, price_list_rate: r.price_list_rate || undefined, description: r.description || undefined, warehouse: r.warehouse || undefined }
    if (sister && r.from_sister) {
      it.azzir_row_from_sister = 1
      it.azzir_supply_company = r.supply_company || undefined
      it.azzir_supply_warehouse = r.supply_warehouse || undefined
    }
    return it
  })
  if (!items.length) { err.value = true; msg.value = 'Add at least one item.'; return }
  // Only the sister-flagged lines need a supply company + warehouse.
  if (sister && items.some((it) => it.azzir_row_from_sister && (!it.azzir_supply_company || !it.azzir_supply_warehouse))) {
    err.value = true; msg.value = 'Each "From sister" line needs a Supply Company and an in-stock Supply Warehouse.'; return
  }
  busy.value = true
  try {
    // The user-chosen document date. For posting_date doctypes set set_posting_time
    // so ERPNext honours a back-/post-dated value instead of resetting it to today.
    const chosenDate = docDate.value || today()
    const dateFields = { [dateField.value]: chosenDate }
    if (dateField.value === 'posting_date') {
      dateFields.set_posting_time = 1
      // Keep the due date valid: ERPNext rejects a due date before the posting date.
      // If moving the posting date forward leaves an earlier due date, push it up.
      const curDue = base.value?.due_date
      if (!curDue || curDue < chosenDate) {
        dateFields.due_date = chosenDate
        if (base.value?.payment_schedule?.length) dateFields.payment_schedule = []
      }
    }
    let saved
    if (base.value) {
      const d = { ...base.value, company: company.value, customer_name: customerName.value || undefined, items, azzir_apply_vat: applyVat.value ? 1 : 0, azzir_hide_part_no: hidePartNo.value ? 1 : 0, azzir_comments: comments.value || undefined, ...dateFields }
      saved = await saveDoc(d)
    } else {
      const d = { doctype: props.doctype, company: company.value, customer_name: customerName.value || undefined, items, azzir_apply_vat: applyVat.value ? 1 : 0, azzir_hide_part_no: hidePartNo.value ? 1 : 0, azzir_comments: comments.value || undefined, ...dateFields }
      if (props.doctype === 'Quotation') { d.quotation_to = 'Customer'; d.party_name = customer.value }
      else d.customer = customer.value
      // Keep the link to the source quotation so the invoice inherits its approval
      // requirement (a below-price quotation -> the invoice also needs approval).
      if (props.initial?.azzir_source_quotation) d.azzir_source_quotation = props.initial.azzir_source_quotation
      saved = await insertDoc(d)
    }
    if (submit) {
      // Submit through the workflow: a below-cost sale is held for approval instead
      // of going straight out. Either way the dialog closes; the list will show the
      // result (Pending Approval for a held below-cost sale).
      await submitSalesDoc(props.doctype, saved.name)
    }
    emit('saved', saved)
  } catch (e) {
    // Server messages can carry HTML (frappe.bold -> <strong>). The SPA shows plain
    // text, so strip tags and decode the few common entities for a clean message.
    const clean = (s) => (s || '').replace(/<[^>]*>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim()
    err.value = true
    msg.value = clean(e?.messages?.map(clean).join(', ')) || clean(e?.message) || 'Could not save.'
  } finally { busy.value = false }
}
</script>
